package com.crms.exception;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(Exception.class)ResponseEntity<?> handle(Exception e){var status=e instanceof org.springframework.security.access.AccessDeniedException?HttpStatus.FORBIDDEN:HttpStatus.BAD_REQUEST;return ResponseEntity.status(status).body(Map.of("message",Objects.toString(e.getMessage(),"Request failed")));}}
